-- SALY ONLY. Normative checkpoints for capital collection, payroll recovery and enterprise self-funding.
-- C1 = normative sources verified. NO C2/C3 closed. NO generic legal approval/permit.
BEGIN;
DO $pre$ DECLARE n integer; BEGIN
 IF (SELECT count(*) FROM saly.programas_investigacion p JOIN saly.proyecto pr ON pr.id=p.proyecto_id WHERE p.codigo='SALY_FONDEO_LEGAL' AND pr.codigo='SALY-001') <> 1 THEN
  RAISE EXCEPTION 'BLOCK_SALY_PROJECT_PROGRAM';
 END IF;
 SELECT count(*) INTO n FROM saly.checkpoints_investigacion c
 JOIN saly.unidades_investigacion u ON u.id=c.unidad_id JOIN saly.programas_investigacion p ON p.id=u.programa_id
 WHERE p.codigo='SALY_FONDEO_LEGAL' AND u.codigo IN ('SALY-LEG-03','SALY-LEG-04','SALY-LEG-05') AND c.codigo='C1' AND c.estado='PENDIENTE'
 AND c.evidencia_principal_id IS NULL;
 IF n <> 3 THEN RAISE EXCEPTION 'BLOCK_SALY_C1_PRECONDITION %',n; END IF;
 IF EXISTS(SELECT 1 FROM saly.evidencias WHERE codigo IN('SALY-EVD-LEG-03-C1','SALY-EVD-LEG-04-C1','SALY-EVD-LEG-05-C1')) THEN
  RAISE EXCEPTION 'BLOCK_SALY_C1_EVIDENCE_EXISTS';
 END IF;
END $pre$;
INSERT INTO saly.evidencias(codigo,tipo,titulo,descripcion,referencia,fecha_evidencia,hechos,estado)
VALUES
('SALY-EVD-LEG-03-C1','NORMATIVA_LEGAL','C1 normativa SBS: captación, préstamos con fondos propios y registro','Res SBS 650-2024 arts.1-7 y SBS 789-2018: los negocios dedicados a préstamos con fondos propios requieren inscripción gratuita/indeterminada y evaluación LA/FT; separar del régimen de captación de fondos ajenos de Ley 26702 art.11. No se halló excepción expresa por ser exclusivamente para empleados; falta definir dedicación de empresa incidental.','Normas oficiales y jurisprudencia Perú revisadas 2026-10-20',DATE '2026-10-20','{"schema":"saly-legal-normative-review/v1","program":"SALY_FONDEO_LEGAL","project":"SALY-001","checkpoint":"C1","reviewed_on":"2026-10-20","jurisdiction":"Peru","business_model":"La plataforma SALY/antecedente TuSueldoYa origina o administra préstamos personales cobrados por descuento de planilla; no se presume pago de sueldo devengado en nombre del empleador.","legal_authorization":false,"definitive_viability_assessed":false,"no_worker_identity_data":true,"next_phase":"C2 aplicación contractual a SALY-ESC-011..016 y evidencia específica del empleador; C3 revisión legal independiente.","unit":"SALY-LEG-03","normative_sources":[{"source":"https://busquedas.elperuano.pe/dispositivo/NL/2264383-1","instrument":"Resolución SBS N°650-2024","articles":"1,2(b),2(c-d),3,4,6,7","facts":["Empresa de préstamos=persona jurídica dedicada a otorgar préstamos de dinero con fondos propios a clientes","Registro previo y obligatorio si encaja en la actividad definida; contempla plataformas tecnológicas","Inscripción gratuita de vigencia indeterminada, Anexo 1 declaración jurada","La inscripción no sustituye requisitos de prevención LA/FT ni, de ser el caso, habilitaciones municipales"],"checked_official":"El Peruano publicada 2024-02-26"},{"source":"https://www.sbs.gob.pe/Portals/0/789-2018.pdf","instrument":"Resolución SBS 789-2018","articles":"2,3,4,5 y 2.3","facts":["Sujeto obligado LA/FT se define por actividad real; al dejar de ejercer puede cesar esa condición","Prevé sistema de prevención y oficial de cumplimiento conforme supuestos"],"checked_official":"SBS PDF 2018, reformas posteriores requieren análisis por ruta"},{"source":"https://www.sbs.gob.pe/prevencion-de-lavado-activos/Sujetos-Obligados/Relacion-de-Sujetos-Obligados","instrument":"SBS relación de sujetos obligados","articles":"Clasificación","facts":["Las empresas dedicadas a préstamos y/o empeño están en lista SPLAFT General"],"checked_official":"Web SBS consultada 2026-10-20"},{"source":"https://www.sbs.gob.pe/boletin/detalleboletin/idbulletin/1241","instrument":"Ley N°26702 art.11, SBS fuente institucional","articles":"11","facts":["Prohibición/limitación de captación habitual de dinero del público sin autorización; distinguir préstamo bilateral de inversión y depósitos"],"checked_official":"SBS; análisis fino de flujos en C2"}],"conclusions_c1":["El hecho de usar capital propio no convierte automáticamente en banco; se evalúa actividad dedicada a prestar, registro UIF/SBS y no captación del público.","La empresa empleadora que concede financiación frecuente y estandarizada mediante SALY no tiene acreditada exención por limitarla al propio personal.","La inscripción SBS para actividad aplicable es gratuita e indeterminada; costo de cumplimiento LA/FT puede ser relevante y no debe confundirse con tarifa del registro.","No presumir que un préstamo de la empresa a SALY y compra de créditos tengan exactamente el mismo tratamiento que prestar al trabajador."],"unresolved_for_c2":["Delimitación oficial entre acto accesorio de apoyo al personal y empresa dedicada a préstamos con plataforma digital.","Determinar operación de cada ruta sin apelar a etiquetas comerciales.","Comprobar procedencia lícita de capital y que no hay captación de terceros; contratos y saldos.","Autoridad SBS/UIF competente y aplicación actualizada reglamentaria a la entidad concreta."]}'::jsonb,'VIGENTE'),
('SALY-EVD-LEG-04-C1','NORMATIVA_LEGAL','C1 normativa laboral: autorización de descuentos con límites remunerativos','Constitución art.24, TUO CPC art.648.6 y STC 02275-2023-PA/TC: autorización contractual de planilla no habilita retenciones que vulneren salario protegido; deuda permanece, la cobranza necesita alternativas lícitas. C1 no certifica contratos TuSueldoYa ni descuentos ilimitados.','Normas oficiales y jurisprudencia Perú revisadas 2026-10-20',DATE '2026-10-20','{"schema":"saly-legal-normative-review/v1","program":"SALY_FONDEO_LEGAL","project":"SALY-001","checkpoint":"C1","reviewed_on":"2026-10-20","jurisdiction":"Peru","business_model":"La plataforma SALY/antecedente TuSueldoYa origina o administra préstamos personales cobrados por descuento de planilla; no se presume pago de sueldo devengado en nombre del empleador.","legal_authorization":false,"definitive_viability_assessed":false,"no_worker_identity_data":true,"next_phase":"C2 aplicación contractual a SALY-ESC-011..016 y evidencia específica del empleador; C3 revisión legal independiente.","unit":"SALY-LEG-04","normative_sources":[{"source":"https://www.tc.gob.pe/jurisprudencia/2025/02275-2023-AA.html","instrument":"STC 02275-2023-PA/TC, Sala Primera, 2025-03-10","articles":"fundamentos 3,7-9,14-19","facts":["Autorización de descuento por planilla no desplaza derecho constitucional a remuneración suficiente","La sentencia aplica marco de inembargabilidad CPC 648.6 a descuentos voluntarios concretos de préstamos de terceros","La deuda no se extingue por impedir descuento indebido; otras vías lícitas de cobro quedan disponibles"],"checked_official":"Web Tribunal Constitucional"},{"source":"https://diariooficial.elperuano.pe/Normas/obtenerDocumento?idNorma=120007","instrument":"TUO Código Procesal Civil","articles":"648 inciso 6","facts":["Remuneraciones y pensiones son inembargables hasta cinco URP, el exceso embargable hasta un tercio","Excepción alimentaria permite embargo hasta 60% de ingresos con deducción de descuentos legales"],"checked_official":"El Peruano normas actualizadas (PDF)"},{"source":"https://diariooficial.elperuano.pe/Normas/obtenerDocumento?idNorma=34","instrument":"TUO DL 728 DS 003-97-TR","articles":"6","facts":["Remuneración deriva de servicios; préstamo privado no constituye automáticamente adelanto salarial del empleador"],"checked_official":"El Peruano"}],"conclusions_c1":["Los convenios de descuento por planilla y autorizaciones del trabajador no justifican retenciones contrarias a los límites constitucionales en casos alcanzados por la jurisprudencia.","Artículo 648.6 regula inembargabilidad; STC 02275-2023 aplicó dicho estándar a descuentos contractuales de créditos. No extrapolar a toda deducción legal de planilla.","No puede presumirse captura del 100% del sueldo, beneficios sociales o liquidación sin análisis específico de límites por concepto y prioridad.","La deuda crediticia conserva existencia pese a límite de descuento: requiere control de insuficiencia, cese y cobranza complementaria."],"unresolved_for_c2":["Evaluar cláusulas históricas de TuSueldoYa de descuentos y liquidaciones, frente a CPC/TC actual.","Construir cálculo de capacidad segura de descuento por tipo de ingreso, mandatos judiciales y límites.","Contratos de préstamo/consentimiento expreso por operación y prueba de que trabajador conoce titular de crédito.","Asignación contractual de riesgo en insuficiencia de planilla y aplicación de otras vías de cobranza."]}'::jsonb,'VIGENTE'),
('SALY-EVD-LEG-05-C1','NORMATIVA_LEGAL','C1 autofondeo: objeto social, préstamo empresarial y alternativa SaaS','Ley 26887 art.11 permite actos lícitos vinculados al objeto social, no actividades reservadas; Código Civil art.1648 sustenta mutuo; DLeg 862 art.1 define fondos de inversión como patrimonios autónomos. Empresa no necesita SAFI solo por usar fondos propios, pero faltan estatuto, encaje SBS y límites laborales.','Normas oficiales y jurisprudencia Perú revisadas 2026-10-20',DATE '2026-10-20','{"schema":"saly-legal-normative-review/v1","program":"SALY_FONDEO_LEGAL","project":"SALY-001","checkpoint":"C1","reviewed_on":"2026-10-20","jurisdiction":"Peru","business_model":"La plataforma SALY/antecedente TuSueldoYa origina o administra préstamos personales cobrados por descuento de planilla; no se presume pago de sueldo devengado en nombre del empleador.","legal_authorization":false,"definitive_viability_assessed":false,"no_worker_identity_data":true,"next_phase":"C2 aplicación contractual a SALY-ESC-011..016 y evidencia específica del empleador; C3 revisión legal independiente.","unit":"SALY-LEG-05","normative_sources":[{"source":"https://www2.congreso.gob.pe/sicr/cendocbib/con4_uibd.nsf/F192BA67C92F4D5C0525804900719FA2/%24FILE/pe061es.pdf","instrument":"Ley General de Sociedades Ley 26887","articles":"11","facts":["Actos relacionados con objeto social que coadyuvan a fines están comprendidos aun si no expresados","No se puede ejercer actividades que la ley reserva a entidades autorizadas"],"checked_official":"Repositorio Congreso, contrastado con texto normativo y actualización del DL 1332"},{"source":"https://diariooficial.elperuano.pe/Normas/obtenerDocumento?idNorma=60","instrument":"Código Civil DL295","articles":"1648,1206,1207,1215","facts":["Mutuo implica obligación de devolver dinero","Cesión de derechos debe constar por escrito y oponibilidad depende de notificación/aceptación al deudor"],"checked_official":"El Peruano"},{"source":"https://www.smv.gob.pe/uploads/Ley_FondosInversion1.pdf","instrument":"TUO DLeg 862 Ley Fondos Inversión","articles":"1","facts":["Fondo es patrimonio autónomo integrado por aportes de partícipes bajo gestión de administradora","La empresa que usa solo su caja no se vuelve fondo de inversión por ese solo hecho"],"checked_official":"SMV TUO histórico; verificar reformas para rutas con terceros"},{"source":"https://busquedas.elperuano.pe/dispositivo/NL/2264383-1","instrument":"Resolución SBS 650-2024","articles":"1-6","facts":["Si una empresa se dedica a prestar fondos propios, se evalúa inscripción SBS/UIF con independencia del nombre del contrato","Registro es gratuito y vigencia indeterminada"],"checked_official":"El Peruano"},{"source":"https://www.tc.gob.pe/jurisprudencia/2025/02275-2023-AA.html","instrument":"TC STC 02275-2023-PA/TC","articles":"3,14-19","facts":["Autorización no permite vulnerar salario protegido"],"checked_official":"TC"}],"route_map":[{"id":"SALY-ESC-011","structure":"Empresa concede mutuo directamente al trabajador; SALY provee tecnología SaaS sin ser acreedor","legal_status":"FACTIBLE_COMO_FIGURA_CONTRACTUAL_NO_HABILITADO_EN_CASO_CONCRETO","requirements":["Poder societario y actividad realmente accesoria u obligación de registro SBS comprobada","Contrato mutuo empresa-trabajador e información sobre costos","Mandato SaaS sin simulación de prestamista","Fondos propios, trazabilidad y descuentos compatibles con Constitución"],"cost_registration_sbs_if_applies_pen":0,"cost_plaft_pen":null},{"id":"SALY-ESC-012","structure":"Empresa presta y SALY administra bolsa mediante mandato, sin titularidad económica de la cartera","legal_status":"REQUISITOS_PENDIENTES","requirements":["Mandato legal y segregación","No custodiar dinero de terceros sin evaluar permisos","Cuenta bancaria y políticas de conciliación"]},{"id":"SALY-ESC-013","structure":"SALY concede mutuo; crédito se cede de inmediato a empresa empleadora","legal_status":"REQUISITOS_PENDIENTES","requirements":["Cesión escrita identificable al nacimiento","Comunicación fehaciente al trabajador","Revisar si compra reiterada de créditos activa supervisión y qué tipo de cartera"]},{"id":"SALY-ESC-014","structure":"Empresa presta a SALY y SALY presta a trabajadores como acreedor","legal_status":"REQUISITOS_PENDIENTES","requirements":["Dos relaciones de préstamo separadas","Capacidad social e inscripción del prestamista si aplicable","Fuente capital, riesgos y cobranzas"]}],"conclusions_c1":["La ausencia de SAFI no prohíbe que empresa empleadora otorgue créditos por contrato civil desde sus propios recursos.","No declarar que autofondeo empresarial está exento del registro SBS: la norma analiza dedicación efectiva y fuentes propias, no denominación ni destino único empleados.","La alternativa SaaS empresa prestamista puede reducir cesión y custodia, pero requiere actos y responsabilidades del prestamista empresarial.","La compra contemporánea y préstamo empresarial a SALY son estructuras distintas, no equivalentes al mero alquiler de software.","La viabilidad legal definitiva es por empresa y ruta tras C2 (estatuto, contratos, capital, SBS, planilla) y C3."],"unresolved_for_c2":["Estatuto/poderes de la empresa concreta; aprobación de política interna de préstamos y presupuesto.","Determinar inscripción SBS por actividad accesoria versus dedicada y control de UIF/LAFT.","Desembolso directo desde cuenta empresaria y límites de mandato operativo SALY.","Verificar costo del compliance y honorarios de adaptación antes de comparar con cesión.","Verificar contratos y facultades del trabajador y la empresa ante riesgo de descuento ilegal."],"implications_financial":["El registro SBS cuando aplica tiene tasa de inscripción cero, pero gastos de cumplimiento y auditoría son variables NO MEDIDOS.","Sin cesión, no hay precio por transferir cartera; separación SaaS con IGV e ingreso de prestamista a analizar por SUNAT.","El principal prestado no es ingreso de SALY SaaS bajo verdadera prestación de servicios, pero reparto real de ingresos requiere revisión tributaria."]}'::jsonb,'VIGENTE');

INSERT INTO saly.checkpoint_evidencias(checkpoint_id,evidencia_id,tipo_relacion)
SELECT c.id,e.id,'SUSTENTA_C1_NORMATIVA'
FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id
JOIN saly.programas_investigacion p ON p.id=u.programa_id
JOIN saly.evidencias e ON e.codigo='SALY-EVD-'||replace(u.codigo,'SALY-','')||'-C1'
WHERE p.codigo='SALY_FONDEO_LEGAL' AND u.codigo IN ('SALY-LEG-03','SALY-LEG-04','SALY-LEG-05') AND c.codigo='C1';

UPDATE saly.checkpoints_investigacion c SET
 estado='DONE',
 dictamen_revision='PASS',
 evidencia_principal_id=e.id,
 ejecutor_ref='GPT_NATIVE_SALY_LEGAL_C1_20261020',
 completado_en=now(),
 nota_revision='PASS C1 exclusivamente: normas oficiales, alcances y riesgos documentados; no demuestra exención SBS ni viabilidad concreta, C2/C3 pendientes.',
 actualizado_en=now()
FROM saly.unidades_investigacion u JOIN saly.programas_investigacion p ON p.id=u.programa_id
JOIN saly.evidencias e ON e.codigo='SALY-EVD-'||replace(u.codigo,'SALY-','')||'-C1'
WHERE c.unidad_id=u.id AND p.codigo='SALY_FONDEO_LEGAL' AND u.codigo IN ('SALY-LEG-03','SALY-LEG-04','SALY-LEG-05') AND c.codigo='C1' AND c.estado='PENDIENTE';

UPDATE saly.unidades_investigacion SET estado_trabajo='EN_CURSO', actualizado_en=now()
WHERE codigo IN ('SALY-LEG-03','SALY-LEG-04','SALY-LEG-05') AND estado_trabajo='PENDIENTE';

DO $verify$ DECLARE n integer; BEGIN
 SELECT count(*) INTO n FROM saly.checkpoints_investigacion c
 JOIN saly.unidades_investigacion u ON u.id=c.unidad_id JOIN saly.evidencias e ON e.id=c.evidencia_principal_id
 WHERE u.codigo IN ('SALY-LEG-03','SALY-LEG-04','SALY-LEG-05') AND c.codigo='C1' AND c.estado='DONE' AND c.dictamen_revision='PASS'
 AND e.codigo='SALY-EVD-'||replace(u.codigo,'SALY-','')||'-C1'
 AND e.hechos->>'legal_authorization'='false';
 IF n<>3 THEN RAISE EXCEPTION 'BLOCK_SALY_C1_READBACK %',n; END IF;
 IF (SELECT count(*) FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id JOIN saly.programas_investigacion p ON p.id=u.programa_id WHERE p.codigo='SALY_FONDEO_LEGAL' AND c.estado='DONE')<>5
 THEN RAISE EXCEPTION 'BLOCK_SALY_C1_PROGRAM_COUNT'; END IF;
 IF EXISTS(SELECT 1 FROM saly.checkpoints_investigacion c JOIN saly.unidades_investigacion u ON u.id=c.unidad_id WHERE u.codigo IN ('SALY-LEG-03','SALY-LEG-04','SALY-LEG-05') AND c.codigo IN ('C2','C3') AND c.estado<>'PENDIENTE')
 THEN RAISE EXCEPTION 'BLOCK_SALY_NO_C2_C3_PROMOTION'; END IF;
END $verify$;
COMMIT;
